        var base=baseValue;
        var exponent=exponentValue;
        var answer=1L;
        while(exponent>0){
            if(exponent and 1L==1L)answer=answer*base%MOD;
            base=base*base%MOD;
            exponent=exponent shr 1
        };
        return answer
    };
    fun append(value:Int){
        val normalized=(value-add+MOD)%MOD;
        values.add(normalized*power(multiply,MOD-2)%MOD)
    };
